-- letras acentuadas: base + acento por cima (ou cedilha embaixo)
local ACENTO = { ["á"] = { "a", "agudo" }, ["à"] = { "a", "grave" }, ["â"] = { "a", "circ" }, ["ã"] = { "a", "til" }, ["é"] = { "e", "agudo" }, ["ê"] = { "e", "circ" },
  ["í"] = { "i", "agudo" }, ["ó"] = { "o", "agudo" }, ["ô"] = { "o", "circ" }, ["õ"] = { "o", "til" }, ["ú"] = { "u", "agudo" }, ["ü"] = { "u", "trema" }, ["ç"] = { "c", "cedilha" },
  ["Á"] = { "A", "agudo" }, ["À"] = { "A", "grave" }, ["Â"] = { "A", "circ" }, ["Ã"] = { "A", "til" }, ["É"] = { "E", "agudo" }, ["Ê"] = { "E", "circ" }, ["Í"] = { "I", "agudo" },
  ["Ó"] = { "O", "agudo" }, ["Ô"] = { "O", "circ" }, ["Õ"] = { "O", "til" }, ["Ú"] = { "U", "agudo" }, ["Ü"] = { "U", "trema" }, ["Ç"] = { "C", "cedilha" } }
local MARCA = { agudo = { { 2, -2 }, { 3, -3 } }, grave = { { 2, -3 }, { 3, -2 } }, circ = { { 1, -2 }, { 2, -3 }, { 3, -2 } }, til = { { 0, -2 }, { 1, -3 }, { 2, -2 }, { 3, -3 } }, trema = { { 1, -2 }, { 3, -2 } }, cedilha = { { 2, 7 }, { 1, 8 } } }
local cacheG = {}
local function glifo(ch)
  local g = cacheG[ch]; if g then return g end
  local s = G[ch]; if not s then return nil end
  g = {}; local y = 0
  for linha in s:gmatch("[^/]+") do for x = 1, #linha do if linha:sub(x, x) == "#" then g[#g + 1] = { x - 1, y } end end; y = y + 1 end
  cacheG[ch] = g; return g
end
function F.escala(tam) return math.max(1, math.floor((tonumber(tam) or 10) / 8 + .5)) end
-- percorre os caracteres em UTF-8
local function letras(t) local out = {}; for ch in tostring(t):gmatch("[%z\1-\127\194-\244][\128-\191]*") do out[#out + 1] = ch end; return out end
function F.largura(t, tam) return #letras(t) * 6 * F.escala(tam) end
-- desenha o texto chamando pixel(x, y, w, h) para cada ponto (o canvas faz o resto)
function F.desenhar(t, x, y, tam, pixel)
  local e = F.escala(tam)
  for i, ch in ipairs(letras(t)) do
    local base, marca = ch, nil
    if ACENTO[ch] then base, marca = ACENTO[ch][1], ACENTO[ch][2] end
    local g = glifo(base) or (base:upper() ~= base and glifo(base:upper())) or (ch ~= " " and glifo("•")) or nil
    local ox = x + (i - 1) * 6 * e
    if g then for _, p in ipairs(g) do pixel(ox + p[1] * e, y + p[2] * e, e, e) end end
    if marca then for _, p in ipairs(MARCA[marca]) do pixel(ox + p[1] * e, y + p[2] * e, e, e) end end
  end
end
return F
